// Pega a resposta bruta do nó Gemini
const item = $input.first().json;

// O texto está em content.parts[0].text (formato nativo do Gemini)
let respostaBruta = '';
try {
  respostaBruta = item.content.parts[0].text;
} catch (e) {
  respostaBruta = item.text || JSON.stringify(item);
}

// Limpa markdown e extrai o JSON
let dados;
try {
  const semMarkdown = respostaBruta.replace(/```json/g, '').replace(/```/g, '').trim();
  const inicio = semMarkdown.indexOf('{');
  const fim = semMarkdown.lastIndexOf('}');
  dados = JSON.parse(semMarkdown.substring(inicio, fim + 1));
} catch (e) {
  // Fallback se o parse falhar
  return [{
    json: {
      intencao: "Outros",
      intencoes_secundarias: [],
      tom: "Neutro",
      prioridade: "P4",
      numero_pedido: null,
      numero_viagem: null,
      transportadora: null,
      valor_divergencia: null,
      prazo_mencionado: null,
      resumo: "Falha ao interpretar resposta da IA",
      motivo: "Erro de parse no JSON",
      requer_humano: true,
      erro_parse: true
    }
  }];
}

// Normaliza nomes de campos (corrige acentos e variações)
const normalizado = {
  intencao: dados["intenção"] ?? dados["intencao"] ?? "Outros",
  intencoes_secundarias: dados["intencoes_secundarias"] ?? [],
  tom: dados.tom ?? "Neutro",
  prioridade: dados.prioridade ?? "P4",
  numero_pedido: dados.numero_pedido ?? null,
  numero_viagem: dados.numero_viagem ?? null,
  transportadora: dados.transportadora ?? null,
  valor_divergencia: dados.valor_divergencia ?? null,
  prazo_mencionado: dados.prazo_mencionado ?? null,
  resumo: dados.resumo ?? "",
  motivo: dados.motivo ?? "",
  requer_humano: dados.requer_humano ?? false
};

return [{ json: normalizado }];

const item = $input.first().json;

const html = `Olá, ${item.Remetente},<br><br>Recebemos sua ocorrência sobre: ${item.Resumo}<br><br>Nossa equipe já está analisando com prioridade ${item.Prioridade}.<br>Caso necessário, entraremos em contato.<br><br>Atenciosamente,<br>Equipe de Operações Logísticas`;

return [{ json: { ...item, htmlPronto: html } }];
